#[path = "solution.rs"]
mod solution;

use solution::{Canvas, PixelOrder};

#[test]
fn constructor_accepts_exact_buffer_and_rejects_mismatch() {
    let canvas = Canvas::new(2, 1, PixelOrder::Rgba, vec![0; 8]).unwrap();
    assert_eq!(canvas.width, 2);
    assert_eq!(canvas.height, 1);
    assert_eq!(canvas.pixels(), &[0; 8]);

    assert!(Canvas::new(2, 1, PixelOrder::Rgba, vec![0; 7]).is_err());
    assert!(Canvas::new(2, 1, PixelOrder::Rgba, vec![0; 9]).is_err());
}

#[test]
fn constructor_reports_dimension_overflow() {
    assert!(Canvas::new(usize::MAX, 2, PixelOrder::Rgba, vec![]).is_err());
    assert!(Canvas::new(usize::MAX, 1, PixelOrder::Rgba, vec![]).is_err());
}

#[test]
fn zero_sized_canvases_are_valid_but_not_drawable() {
    let mut canvas = Canvas::new(0, 3, PixelOrder::Rgba, vec![]).unwrap();
    assert!(canvas.put_pixel(0, 0, [1, 2, 3, 4]).is_err());
    assert!(canvas.pixels().is_empty());

    let mut canvas = Canvas::new(3, 0, PixelOrder::Rgba, vec![]).unwrap();
    assert!(canvas.put_pixel(0, 0, [1, 2, 3, 4]).is_err());
    assert!(canvas.pixels().is_empty());
}

#[test]
fn rgba_and_bgra_store_channels_in_required_order() {
    let mut rgba = Canvas::new(1, 1, PixelOrder::Rgba, vec![0; 4]).unwrap();
    rgba.put_pixel(0, 0, [10, 20, 30, 40]).unwrap();
    assert_eq!(rgba.pixels(), &[10, 20, 30, 40]);

    let mut bgra = Canvas::new(1, 1, PixelOrder::Bgra, vec![0; 4]).unwrap();
    bgra.put_pixel(0, 0, [10, 20, 30, 40]).unwrap();
    assert_eq!(bgra.pixels(), &[30, 20, 10, 40]);
}

#[test]
fn writes_only_the_selected_row_major_pixel() {
    let mut canvas = Canvas::new(2, 2, PixelOrder::Rgba, vec![9; 16]).unwrap();
    canvas.put_pixel(1, 1, [1, 2, 3, 4]).unwrap();
    assert_eq!(canvas.pixels(), &[9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 1, 2, 3, 4]);
}

#[test]
fn boundary_and_large_coordinates_error_without_mutation_or_panic() {
    let mut canvas = Canvas::new(2, 2, PixelOrder::Rgba, vec![7; 16]).unwrap();
    let before = canvas.pixels().to_vec();

    assert!(canvas.put_pixel(2, 0, [1, 2, 3, 4]).is_err());
    assert_eq!(canvas.pixels(), before.as_slice());
    assert!(canvas.put_pixel(0, 2, [1, 2, 3, 4]).is_err());
    assert_eq!(canvas.pixels(), before.as_slice());
    assert!(canvas.put_pixel(usize::MAX, usize::MAX, [1, 2, 3, 4]).is_err());
    assert_eq!(canvas.pixels(), before.as_slice());
}

